'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var minstd = require( '@stdlib/random/base/minstd' ).factory;
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var dkmeansInitPlusPlus = require( './../lib/ndarray.js' );


// FIXTURES //

var ROW_MAJOR_DATA = require( './fixtures/row_major.json' );
var COLUMN_MAJOR_DATA = require( './fixtures/column_major.json' );
var OFFSET_ROW_MAJOR_DATA = require( './fixtures/offsets/row_major.json' );
var OFFSET_COLUMN_MAJOR_DATA = require( './fixtures/offsets/column_major.json' );
var NEGATIVE_STRIDES_ROW_MAJOR_DATA = require( './fixtures/negative-strides/row_major.json' );
var NEGATIVE_STRIDES_COLUMN_MAJOR_DATA = require( './fixtures/negative-strides/column_major.json' );
var MIXED_STRIDES_ROW_MAJOR_DATA = require( './fixtures/mixed-strides/row_major.json' );
var MIXED_STRIDES_COLUMN_MAJOR_DATA = require( './fixtures/mixed-strides/column_major.json' );
var LARGE_STRIDES_ROW_MAJOR_DATA = require( './fixtures/large-strides/row_major.json' );
var LARGE_STRIDES_COLUMN_MAJOR_DATA = require( './fixtures/large-strides/column_major.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dkmeansInitPlusPlus, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 20', function test( t ) {
	t.strictEqual( dkmeansInitPlusPlus.length, 20, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if `k` is greater than `M`', function test( t ) {
	var data;
	var opts;

	data = ROW_MAJOR_DATA;
	opts = {
		'prng': minstd({
			'seed': data.seed
		})
	};

	t.throws( badValue, RangeError, 'throws an error' );
	t.end();

	function badValue() {
		dkmeansInitPlusPlus( 1, data.N, data.k, data.trials, data.metric, new Float64Array( data.X ), data.strideX1, data.strideX2, data.offsetX, new Float64Array( data.out ), data.strideO1, data.strideO2, data.offsetO, new Float64Array( data.W1 ), data.strideW1, data.offsetW1, new Int32Array( data.W2 ), data.strideW2, data.offsetW2, opts );
	}
});

tape( 'the function throws an error when trials is less than or equal to zero', function test( t ) {
	var data;
	var opts;

	data = ROW_MAJOR_DATA;
	opts = {
		'prng': minstd({
			'seed': data.seed
		})
	};

	t.throws( badValue( 0 ), RangeError, 'throws an error when provided ' + 0 );
	t.throws( badValue( -1 ), RangeError, 'throws an error when provided ' + -1 );
	t.end();

	function badValue( value ) {
		return function badValue() {
			dkmeansInitPlusPlus( data.M, data.N, data.k, value, data.metric, new Float64Array( data.X ), data.strideX1, data.strideX2, data.offsetX, new Float64Array( data.out ), data.strideO1, data.strideO2, data.offsetO, new Float64Array( data.W1 ), data.strideW1, data.offsetW1, new Int32Array( data.W2 ), data.strideW2, data.offsetW2, opts );
		};
	}
});

tape( 'the function throws an error if provided an unsupported metric', function test( t ) {
	var values;
	var data;
	var opts;
	var i;

	data = ROW_MAJOR_DATA;
	opts = {
		'prng': minstd({
			'seed': data.seed
		})
	};

	values = [
		'foo',
		'bar',
		'beep',
		'boop'
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dkmeansInitPlusPlus( data.M, data.N, data.k, data.trials, value, new Float64Array( data.X ), data.strideX1, data.strideX2, data.offsetX, new Float64Array( data.out ), data.strideO1, data.strideO2, data.offsetO, new Float64Array( data.W1 ), data.strideW1, data.offsetW1, new Int32Array( data.W2 ), data.strideW2, data.offsetW2, opts );
		};
	}
});

tape( 'the function returns the output array when k is less than one (row-major)', function test( t ) {
	var expected;
	var data;
	var opts;
	var out;
	var i;

	data = ROW_MAJOR_DATA;
	opts = {
		'prng': minstd({
			'seed': data.seed
		})
	};
	out = dkmeansInitPlusPlus( data.M, data.N, 0, data.trials, data.metric, new Float64Array( data.X ), data.strideX1, data.strideX2, data.offsetX, new Float64Array( data.out ), data.strideO1, data.strideO2, data.offsetO, new Float64Array( data.W1 ), data.strideW1, data.offsetW1, new Int32Array( data.W2 ), data.strideW2, data.offsetW2, opts );

	expected = new Float64Array( data.out );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( isAlmostSameValue( out[ i ], expected[ i ], 0 ), true, 'returns expected value' );
	}
	t.end();
});

